using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(NotesTool.AddNote),
    AIFunctionFactory.Create(NotesTool.GetNotes),
};

// --- Create the research agent using Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using the search tool (perform 2-3 searches with different queries).
        2. Take notes on the key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a well-structured summary.

        Always cite your sources. Be thorough but concise.
        """,
    tools: tools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync(conversationId: "research-session");

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Message.Text);

// --- Tool implementations ---

/// <summary>Simulates web search functionality.</summary>
static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // In production, replace with a real search API (Bing Search, Google Custom Search, etc.)
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        await Task.Delay(100); // Simulate network latency

        // Simulated search results for demonstration purposes
        return $"""
            Search results for "{query}":

            1. Wikipedia - {query}
               Summary: {query} is a widely discussed topic with multiple facets. 
               Recent developments include advancements in the field and growing public interest.
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}

            2. Research Paper - "Advances in {query}"
               Abstract: This paper explores recent breakthroughs and challenges related to {query},
               highlighting key trends and future directions.
               URL: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}

            3. News Article - "The State of {query} in 2026"
               A comprehensive overview of where {query} stands today, covering industry adoption,
               challenges, and expert predictions for the next decade.
               URL: https://news.example.com/{Uri.EscapeDataString(query)}
            """;
    }
}

/// <summary>Note-taking tool that persists findings during research.</summary>
static class NotesTool
{
    private static readonly List<string> _notes = [];

    [Description("Adds a research note to the notebook. Use this to record key findings from searches.")]
    public static string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken during this research session.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n\n---\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

